110	    const permute = <T>(items: readonly T[], seed: number): T[] => { const copy = [...items]; let state = seed; for (let index = copy.length - 1; index > 0; index -= 1) { state = (state * 1103515245 + 12345) % 2147483648; const swap = state % (index + 1); [copy[index], copy[swap]] = [copy[swap]!, copy[index]!]; } return copy; };
111	    const reorderKeys = <T extends object>(value: T): T => Object.fromEntries(Object.entries(value).reverse()) as T;
112	    for (let seed = 1; seed <= 20; seed += 1) {
113	      const base = camil(true);
114	      const shuffled: ExitCostInput = {...base, series: permute(base.series, seed).map((series) => reorderKeys({...series, mechanisms: permute(series.mechanisms, seed + 1).map(reorderKeys)}))};
115	      const again = estimateExitCostBySeries(seed % 2 ? reorderKeys(shuffled) : shuffled);
